<script setup>import{Head,Link,router}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';import{formatDateTime}from'../../utils/date.js';defineProps({notifications:Object,preferences:Array})</script>
<template><AppLayout><Head title="اعلان‌ها"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h1 class="text-xl font-bold">اعلان‌ها</h1><Link href="/notifications/read-all" method="patch" as="button" class="rounded-xl border px-4 py-2">خواندن همه</Link></div><div class="mt-5 space-y-3"><article v-for="item in notifications.data" :key="item.id" class="rounded-xl border p-4" :class="item.read_at?'bg-white':'border-teal-300 bg-teal-50'"><div class="flex flex-wrap justify-between gap-3"><strong>{{item.data.title}}</strong><time class="text-xs text-slate-500" :datetime="item.created_at">{{formatDateTime(item.created_at)}}</time></div><p class="mt-2 text-sm text-slate-700">{{item.data.message}}</p><div class="mt-3 flex gap-3"><Link v-if="!item.read_at" :href="`/notifications/${item.id}/read`" method="patch" as="button" class="text-sm text-teal-700">خوانده شد</Link><Link v-if="item.data.action_url" :href="item.data.action_url" class="text-sm text-teal-700">مشاهده</Link></div></article><p v-if="!notifications.data.length" class="rounded-xl border border-dashed p-6 text-center text-slate-500">اعلان جدیدی ندارید.</p></div><div class="mt-4 flex flex-wrap gap-2"><Link v-for="link in notifications.links" :key="link.label" :href="link.url||'#'" v-html="link.label" class="rounded border px-3 py-1" :class="{'opacity-40':!link.url,'bg-teal-50':link.active}"/></div></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">تنظیمات اعلان</h2><label v-for="item in preferences" :key="item.category" class="mt-3 flex items-center gap-3"><input type="checkbox" :checked="item.enabled" @change="router.put('/notification-preferences',{category:item.category,enabled:$event.target.checked})">{{item.label}}</label><p class="mt-3 text-xs text-slate-500">اعلان‌های مهم دسترسی دوره و تخصیص تدریس همیشه فعال هستند.</p></section></div></AppLayout></template>
